T[43633]="Jaina, a jovem aprendiz, é bastante atraente para uma humana. Espero que ela reconheça minha elegância e meu poder."
T[43634]="Escute, pequena fonte dos desejos. Se sabe o que é bom para você, entregue-me todo o seu poder."
T[43635]="Às vezes gostaria que alguém viniese e me desse um enorme abraço."
T[43636]="Só uma vez eu gostaria que alguém me cumprimentasse sem fazer uma piada idiota sobre gnomos ou viagem no tempo."
T[43637]="Brann Barbabronze esteve aqui."
T[43638]="Desejo me aposentar um dia em uma pequena fazenda com muitos cães para me fazer companhia."
T[43639]="Já tenho um reino em perspectiva, uma terra que governar. Que mais posso pedir? Talvez um bolhito gelado..."
