T[43662]="Você certamente espera que este machado esteja muito afiado. Não está. Os vrykul deviam contar com sua força descomunal para destruir os inimigos."
T[43665]="Um final trágico para uma história triste. Tomara que o abuso de Malygos contra Keristrasza não a tenha enlouquecido."
