T[97397]="Os Pontos de Temporada representam seu progresso durante a temporada. Eles desbloqueiam recompensas cosméticas na coleção de aparências, também disponíveis nos reinos principais!"
T[97398]="@|cFFCC0000Exclusivo dos Reinos Sazonais|r@Este item desbloqueia sua Coleção de Conquistas Sazonais e permite ganhar Pontos de Temporada. Esses pontos podem ser gastos para desbloquear itens cosméticos exclusivos!"
T[97751]="Um troféu obtido ao concluir provas, que pode ser trocado por recompensas.\n\nEle pode ser entregue a um Mestre de Desafios, em qualquer capital ou área inicial, em troca de itens cosméticos exclusivos."
T[97871]="Apenas afeta ao personagem que o usa."
