T[352621]="Um cajado de comando perdido... Me pergunto para que o usaba ela?"
T[354154]="Pouco resta da armadura deste aventureiro, mas talvez que suficiente para envolver seus munhecas."
T[354199]="Vários jovens valentes participaram de uma competição para ver quem conseguia lançar o dardo mais longe. Apenas um caiu longe demais para ser recuperado."
T[354231]="A tênue luz desta lanterna vai acompanhada do fraco som de solhozos..."
T[354236]="Antigamente disenhado para proteção a seu portador do dano, este colar foi retorcido por seu proximidade ao Atal'ai."
T[354266]="Parece ter sido deixado como lembrança pelo construtor deste estranho santuário. Pela arquitetura, ele deve ter vindo de uma terra distante."
T[354448]="'Zael' está gravado neste amuleto em uma antiga escritura."
T[354455]="'Kire' está gravado nesta lâmina em uma antiga escritura."
T[354459]="Seus gritos são o monumento sobre o qual seu nome será gravado para sempre."
T[354469]="Um pedaço de um mundo destruído há muito tempo, guardado por Medivh em seu porão como curiosidade."
T[354660]="Uma página arrancada do Codice de Segredos."
T[355165]="Varinhas como esta, entalhadas na forma de uma estrela sombria, eram entregues aos servos mais leais da Rainha Sybelh. Apenas uma sobreviveu a todos esses anos, mas Stromgarde parece disposta a se desfazer dela..."
T[355178]="Uma criação experimental do Artífice Baraal, feita para proteção ao usuário contra compulsiones mentales."
T[355199]="Não está seguro exatamente de que tipo de carne é esta em realidade, e não está seguro de que saber."
T[358721]="O boomerang perdido do capitão Dubi."
T[375250]="Conquistadas por suas próprias ações, estas runas concedem poder para seu progresso e personalização. Reúna-as em abundância ao longo de suas aventuras."
