T[410085]="Sente uma presença reconfortante, mas fria."
T[410160]="A quem vai chamar? A Cruzada!"
T[415004]="Droga, eles realmente não gostam de fogo."
T[415026]="Ninguém chegará mais a isto.."
T[415049]="Com apenas um cheiro jurarás que o tempo se desacelera. O lhaman uma ensonhação de Pó. Eu o lhamo opções de vidàmentables."
T[415052]="Perdido em batalha, um berloque tomado pela cobiça esquecida de um pirata."
T[415054]="O mais requintado exemplo."
T[415059]="É possível ouvir o mar bem baixinho ao aproximá-la do ouvido."
T[415065]="Advertência parental: conteúdo explícito recomendado"
T[415093]="Não muitos o sobreviven."
T[415151]="Provavelmente é melhor não pensar no uso anterior."
T[415160]="Imbuído pelo poder ressonante dos rituais de vínculo com a terra de Martuk, este capuz responde a cada encantamento, chamando rochas e pedras para se erguerem sob seu comando."
