T[426758]="Roubado a um gnomo muito enfadado"
T[450263]="Uma varinha esculpida em osso de Galgosh."
T[450264]="Não o compartas com seus seres queridos."
T[450512]="Quem corte a fila, tendrá que ir a esvaziar o recipiente."
T[450515]="Ainda brilha com veneno."
T[450521]="Cáries podem deixar qualquer um furioso!"
T[450525]="As lendas falam de um pico solitário onde os relâmpagos caem como um relógio a cada lua cheia. A madeira da varinha veio de uma árvore atingida não uma, mas duas vezes — seu poder agora está entrelaçado nesta relíquia da há muito perdida linhagem Thunderfall."
T[450526]="Canhões que te protegen confiablemente dos Bandidos... No seu maioria."
T[450528]="Você... pegou... veladora?"
T[450551]="Apenas desejo haver pedido chegar a essa última ilha. O Peixe sempre é mais grande do outro lado."
T[450552]="Sou um mineiro sortudo ou que?"
T[450559]="Estas anotações registram a queda de um drone na loucura durante os experimentos."
T[450584]="Amor louco."
T[450616]="Snagglerspear é famoso por usar este apito para caçar kodos, soprando-o ocasionalmente para sinalizar o ataque de sua manada."
T[450641]="Ouve um grito fraco procedente da espada."
T[450644]="Mankrik já perdeu o bastante... Talvez seja melhor colocar isto de volta."
T[450807]="Um ramosilho de Bathran, um treant mágico que pagó o preço dos experimentos dos Forsaken na zona."
T[450809]="Ninguém gosta de cáries."
T[450871]="Deveria tocar isto?"
T[451046]="Um fragmento reluzente manchado pela energia Félida."
T[451047]="Contém apenas um pedaço do poder de Aessina."
