T[509903]="Continua esta guia de 1 passos e te convertirás instantaneamente em um famoso flexor！"
T[515031]="Comer isto te matará... Isso é todo."
T[515037]="Gravado com runas malvadas."
T[515039]="Olvidadeo há muito tempo."
T[515046]="Surpreendentemente resistente, ajusta-se bem quando enrolado como uma corda e amarrado à cintura."
T[515047]="Não estou muito seguro de onde tem estado."
T[515150]="Esta mão gravada com runas parece apartar as lâminas de espadas."
T[515208]="Se quedó no fogo um pouco mais que a maioria."
T[515216]="Ao final, às vezes o único que resta por fazer é correr."
T[515222]="Temperado em chama vivo."
T[515223]="Endurecido pelas chamas que alguma vez desafió."
T[515251]="O Amor e o Calor van da mão."
T[515284]="Os glifos no cinto brilham com o poder de uma era esquecida."
T[515286]="Armadura forjada para uma batalha do passado."
T[515292]="A lixo de um é..."
T[515365]="Vibra com a mesma frecuência que as Pylons."
T[515382]="Esta arma de arremesso já fez parte de uma coleção dos Fab Four. Não se deixe enganar pelo trocadilho: ela ainda desfere um golpe digno de uma turnê mundial."
T[515531]="No seu mão, emite suaves vibrações interrumpidas por fracos chasquidos. Talvez seja melhor deixá-lo a um lado."
T[515537]="Aumenta a velocidade de corrida em 300%"
T[515603]="Entalhado no corpo de um Andarilho dos Penhascos. A julgar pelo destino dos pelursos, os gigantes não acharam isso muito engraçado."
T[515604]="Um zumbido suave e melódico ressoa desta lira antiga. É impossível não se perguntar como ela permaneceu intocada durante todos esses anos..."
T[515608]="Com muito esforço, finalmente conseguiu remover este selo da antiga estátua."
T[515621]="Uma imitação de um anel muito mais poderoso que se perdeu há tempo."
T[515623]="Uma representação metafórica da força de Azshara — embora seu poder também pareça bastante literal."
T[515624]="Eldara inscribió Runas Beth'Amara em cristais como este para proteção a cidade, mas até esse poder não foi suficiente para salvarla do Desgarramento."
T[515625]="Eldara inscreveu runas Markri em armas como esta para defender a cidade dos invasores. Os encantamentos que a animavam desapareceram há muito tempo, mas ela ainda funciona de modo semelhante a uma besta moderna."
T[515626]="Estas ombreiras ainda carregam uma fraca ressonância do poder do Sumo Sacerdote Zin-Malor, um mistério que continua intrigando os historiadores."
T[515629]="Estas terras levam o nome de Sua Radiância, e em seu nome nós as reivindicaremos!"
T[515634]="As runas gravadas neste cajado ainda brilham com o poder de um antigo escriba que desapareceu de Azeroth há muito tempo."
T[515676]="Engenharia Goblin: Lembre-se, apenas precisa funcionar uma vez!"
T[515681]="Forjado com ferro de fazenda e abençoado por fieles colonos"
T[515703]="Pouco resta do corpo que um dia usou estes protetores, mas a magia persistente tecida no tecido rasgado ainda permanece."
T[515720]="Riscado por dentes e garras, este humilde anel narra a última história de um caçador que nunca regresó do florestas selvagem."
T[515733]="Ressoa com o fraco batimento de um mal ancestral."
T[515737]="Um manual gasto com secções inteiras tachadas e reemplazadas por \\'-50 DKP!\\' em vermelho, letra negrilha."
T[515791]="A magia das cavernas penetrou profundamente na madeira, fazendo-a ressoar com um poder silencioso e atemporal."
T[515827]="Dá conta do serviço."
T[515835]="Cuidado: a lente está quebrada. Não deixe os estilhaços entrarem nos olhos!"
T[515839]="Confiança cosmética!"
T[515844]="A semilhàte com vida e te sente crescer um centímetro de altura."
T[555555]="Um amuleto carregado com a mana dos magos mortos."
T[558704]="Ensina a invocar o Escudo Zandalari. Ele é exibido nas suas costas."
T[558960]="A poção ainda não está pronta. Uma nota presa ao lado lista os ingredientes que Dulcinea já comprou — devidamente riscados — e os que ainda precisa obter: pétalas da flor de Elgris, concentrado de licor Dun Kazad, suco de abóbora e um olho de murloc."
T[558970]="<Embora este pingente não tem valor sentimental para você, pode tenerlo para Thariel, o irmão de Elydna."
T[559143]="Uma tira de carne apodrecida há muito tempo. A doçura enjoativa da decomposição entorpece os sentidos."
T[559144]="Amálgama de carne boa, retirada do Ossuário Enluarado. Ela exsuda podridão e fede a carniça. Mesmo assim, desperta o apetite de todos os druidas ao redor."
T[559145]="Amálgama abençoada de carne, umedecida e fortalecida pelo toque suave da lua."
T[559851]="O diário de Lorde Arathon, filho de Servin Darengar e herdeiro da família.\n\nAs anotações são confusas e beiram o enigmático. Algumas páginas parecem mais um livro-caixa do que um diário pessoal. Essa ambiguidade deliberada só aumenta as suspeitas. As palavras 'Ealdir', 'poço', 'carregamento' e 'caverna' aparecem repetidamente."
T[560158]="\"Entré como uma bola destruidora\""
T[650015]="Um guia gasto pela natureza que ainda leva as marcas do florestas - agujas de pinho, musgo e terra."
T[650153]="Um pergaminho etéreo que contém mapas estelares que parpadean com luz real de estrelas, quentes ao toque apesar de seu frieza celestial."
T[663318]="Uma cópia de um diário escrito por Krelin, o Espadachim."
