T[777900]="Uma Caixa Etérea que contém itens cosméticos aleatórios do Bazar Etéreo. Há uma pequena chance de receber a montaria exclusiva da temporada!"
T[777903]="Está com sorte? Abra esta caixa para receber um Estandarte de Propriedade aleatório."
T[777992]="Estes dados não são mais usados e podem ser excluídos.\n\nVocê pode escolher novamente seus feitiços iniciais pela Evolução do Personagem (tecla N) antes de alcançar o nível 10."
T[777998]="Maximiza uma Profissão de seu elecção. Você precisará aprender a profissão também."
T[777999]="Forja um item em Sangue, transformando-o em equipamento JxJ. Isso remove o poder JxA e o substitui por poder JxJ. Itens Heroicos, Míticos ou Ascendidos são convertidos em uma versão normal Forjada em Sangue. Cuidado: este processo é IRREVERSÍVEL."
T[808965]="Bem feito, duradouro e obtido de forma ética."
T[824385]="Confesso que não sigo filosofia alguma. Pertenço ao mundo real, pois a realidade não cabe em nenhuma ideologia. Essas ideias são abstrações, confortos que abraçamos por medo de fazer perguntas sem a promessa de respostas."
T[824396]="Elmo usado pelos zelotes da Cidade Radiante. Um leve formigamento percorre quem se aproxima. Embora a origem do culto esteja envolta em mistério, alguns sussurram sobre um deus radioativo que apareceu diante de Sua Majestade Radiante e lhe concedeu um propósito divino."
T[824400]="Lança feita com um galho do ninho do Grande Condor. Dizem que os galhos vieram originalmente de uma Árvore do Mundo, derrubada por uma calamidade ainda maior."
T[835211]="Deslizaos."
T[898070]="Sopra uma trompa estridente, atraindo inimigos em um raio de 30 metros."
