T[1388227]="Antigamente disenhado para proteção a seu portador do dano, este colar foi retorcido por seu proximidade ao Atal'ai."
T[1388369]="Com apenas um cheiro jurarás que o tempo se desacelera. O lhaman uma ensonhação de Pó. Eu o lhamo opções de vidàmentables."
T[1388372]="Perdido em batalha, um berloque tomado pela cobiça esquecida de um pirata."
T[1388374]="O mais requintado exemplo."
T[1388379]="É possível ouvir o mar bem baixinho ao aproximá-la do ouvido."
T[1388479]="Imbuído pelo poder ressonante dos rituais de vínculo com a terra de Martuk, este capuz responde a cada encantamento, chamando rochas e pedras para se erguerem sob seu comando."
T[1388543]="As lendas falam de um pico solitário onde os relâmpagos caem como um relógio a cada lua cheia. A madeira da varinha veio de uma árvore atingida não uma, mas duas vezes — seu poder agora está entrelaçado nesta relíquia da há muito perdida linhagem Thunderfall."
T[1388546]="Você... pegou... veladora?"
T[1388570]="Apenas desejo haver pedido chegar a essa última ilha. O Peixe sempre é mais grande do outro lado."
T[1388578]="Estas anotações registram a queda de um drone na loucura durante os experimentos."
T[1388633]="Snagglerspear é famoso por usar este apito para caçar kodos, soprando-o ocasionalmente para sinalizar o ataque de sua manada."
T[1388794]="Um fragmento reluzente manchado pela energia Félida."
T[1388818]="Ei, desde que funcione."
T[1388920]="Ao final, às vezes o único que resta por fazer é correr."
T[1388927]="Endurecido pelas chamas que alguma vez desafió."
T[1388967]="Infundido com magia retorcida, o fragmento metálico late com um zumbido antigo."
T[1389036]="No seu mão, emite suaves vibrações interrumpidas por fracos chasquidos. Talvez seja melhor deixá-lo a um lado."
T[1389048]="Eldara inscribió Runas Beth'Amara em cristais como este para proteção a cidade, mas até esse poder não foi suficiente para salvarla do Desgarramento."
T[1389078]="Um manual gasto com secções inteiras tachadas e reemplazadas por \\'-50 DKP!\\' em vermelho, letra negrilha."
T[1389109]="A semilhàte com vida e te sente crescer um centímetro de altura."
T[1389901]="Confesso que não sigo filosofia alguma. Pertenço ao mundo real, pois a realidade não cabe em nenhuma ideologia. Essas ideias são abstrações, confortos que abraçamos por medo de fazer perguntas sem a promessa de respostas."
